// Generated by the /gstack-ship test coverage audit (pass 1).
// Value: protects=a picture written into the page as data is re-encoded whole, however large it is; fails_when=chunking is removed (argument limit throws) or a chunk boundary drops or repeats bytes; why_new=images.spec.ts embeds pictures of a few dozen bytes, never past one chunk; seam=none; no_claim=picture validity (bytes are arbitrary)
import { expect, test } from 'vitest'

import { decodeBase64 } from './decodeBase64'
import { encodeBase64 } from './encodeBase64'

test('a picture of a million bytes, many chunks long, is encoded whole and decodes back byte for byte', () => {
  // Arrange
  // Each byte holds its position's low bits mixed with its chunk number: a chunk dropped, repeated or
  // moved changes the decoded bytes
  const bytes = Uint8Array.from({ length: 1_048_576 }, (_, index) => (index ^ (index >> 15)) & 0xff)

  // Act
  const encoded = encodeBase64(bytes)
  const decoded = decodeBase64(encoded)

  // Assert
  expect(encoded.length).toBe(1_398_104)
  expect(decoded).toEqual(bytes)
})
